function eoSignIn(socket, signIn, messageError, modPlayer){
    if(!signIn){
        socket.emit(EO_SIGN_IN, {signIn: signIn, messageError: messageError});
    } else {
        var auxUser = getUserOnlineByName(modPlayer.name);

        //Usuario conectado previamente    
        if(auxUser!=false){
            if(auxUser.inGame && games[auxUser.table]!=null){ //Usuario en partida
                console.log("--->**(sign-in) Usuario "+auxUser.name+" conectado previamente. En partida. Mesa: "+auxUser.table);
                games[auxUser.table].playerLeave = auxUser.chair;
                games[auxUser.table].gameFinished = true;
                updateGameFinished(auxUser.table);
                endGame(auxUser.table, auxUser.chair);
            } else {
                console.log("--->**(sign-in) Usuario "+auxUser.name+" conectado previamente. Mesa: "+auxUser.table+"\tSilla: "+auxUser.chair);
                if(auxUser.table!=-1 && auxUser.chair!=-1){
                    tables[auxUser.table][auxUser.chair] = -1;
                }
            }
            
            //Se desconecta el ID anterior
            deleteUserAndSocket(auxUser.id);           
        } 
        
        var auxSO = getUserOnline(socket.id);
        auxSO.id = socket.id;
        auxSO.name = modPlayer.name;
        auxSO.table = modPlayer.table;
        auxSO.chair = modPlayer.chair;
        auxSO.premium = modPlayer.premium;
        auxSO.userIcon = modPlayer.userIcon;
        //Públicas
        auxSO.position_PP = modPlayer.position_PP;
        auxSO.points_PP = modPlayer.points_PP;
        auxSO.ratio_PP = modPlayer.ratio_PP;
        auxSO.nWon_PP = modPlayer.nWon_PP;
        auxSO.nLost_PP = modPlayer.nLost_PP;
        auxSO.nRevoke_PP = modPlayer.nRevoke_PP;
        //Temporada 0
        auxSO.position_T0 = modPlayer.position_T0;
        auxSO.points_T0 = modPlayer.points_T0;
        auxSO.ratio_T0 = modPlayer.ratio_T0;
        auxSO.nWon_T0 = modPlayer.nWon_T0;
        auxSO.nLost_T0 = modPlayer.nLost_T0;
        auxSO.nRevoke_T0 = modPlayer.nRevoke_T0;
        //Temporada 1
        auxSO.position_T1 = modPlayer.position_T1;
        auxSO.points_T1 = modPlayer.points_T1;
        auxSO.ratio_T1 = modPlayer.ratio_T1;
        auxSO.nWon_T1 = modPlayer.nWon_T1;
        auxSO.nLost_T1 = modPlayer.nLost_T1;
        auxSO.nRevoke_T1 = modPlayer.nRevoke_T1;
        
        
        console.log("--->SIGN-IN("+usersOnline.length+"): "+modPlayer.name+"\t"+socket.id);
        socket.emit(EO_SIGN_IN, {signIn: signIn, messageError: messageError, usersOnline: usersOnline, newsVersion: newsVersion, arrayNews: arrayNews, 
             pointsForWinning: POINTS_FOR_WINNING, pointsForLost: POINTS_FOR_LOST, pointsForLeaving: POINTS_FOR_LEAVING});
        socket.broadcast.emit(EO_USERS_ONLINE, usersOnline);

        mongoJS.rankingPlayers(socket);

        logsJS.showPlayersLog(flagShowPlayersConnected, flagShowPlayersDetail, socketsOnline, usersOnline, NUM_PLAYERS_IA);
    }
}

