function eoReconnectToGame(socket, _table){
    var serverGame = games[_table];
    var _user = getUserOnline(socket.id);
    var _aButtonEvent = serverGame.arrayButtonEventPhase;

    console.log("*****************************************Usuario RECONECTADO: "+_user.name+" - "+socket.id+"\tMesa: "+_table);
    
    //Elimina el jugador abandonado al reconectarse
    for(var i=0; i<serverGame.chairsLeave.length; i++){
        if(serverGame.chairsLeave[i]==_user.chair){
            serverGame.chairsLeave.splice(i,1);
        }
    }
    
    //Envía evento de reconexión
    var notice = getUsername(socket.id)+" se ha reconectado.";
    for(var i=0; i<NUM_PLAYERS; i++){
        var auxUser = serverGame.players[i];
        if(auxUser!=null){
            //io.to(auxUser.id).emit(EO_NOTICE_SERVER, {title: "Reconexión a partida", notice: notice});
            io.to(auxUser.id).emit(EO_PLAYER_GAME_RECONNECTED, {playerOut: false, chair: _user.chair});
        }
    }

    socket.broadcast.emit(EO_USERS_ONLINE, usersOnline);
    socket.emit(EO_USERS_ONLINE,usersOnline);
    socket.emit(EO_RECONNECT_TO_GAME, {user: _user, aButtonEvent: _aButtonEvent, serverGame: serverGame});
}
