function updateGameFinished(_table){ //auxSG=Objeto serverGame       pX=playerX
    var auxSG = games[_table];
    if(updateGamesAvailable){
        if(auxSG.gameStarted){
            if(!auxSG.gameUpdated){
                //if(auxSG.players[0].ia || auxSG.players[1].ia || auxSG.players[2].ia || auxSG.players[3].ia) return;

                var finished = auxSG.gameFinished;
                var completed = auxSG.gameCompleted;
                var type = auxSG.typeGame;
                var playerLeave = auxSG.playerLeave;
                var chairsL = auxSG.chairsLeave;

                var sets = auxSG.sets;
                var points = auxSG.points;

                var p0 = getUsername(auxSG.players[0].id);
                var p1 = getUsername(auxSG.players[1].id);
                var p2 = getUsername(auxSG.players[2].id);
                var p3 = getUsername(auxSG.players[3].id);

                //var pairLeave = -1;
                var playerRevoke = -1;
                var pWon = -1;

                if(completed){ //LA PARTIDA HA FINALIZADO CORRECTAMENTE (Completada)
                    if(sets[0]>sets[1]) pWon = 0; //Pareja 1 gana
                    else pWon = 1;
                } else if(playerLeave!=-1){ //JUGADOR HA SOLICITADO ABANDONAR
                    playerRevoke = playerLeave;
                    /*if(playerLeave==0 || playerLeave==2) pairLeave = 0;
                    if(playerLeave==1 || playerLeave==3) pairLeave = 1;*/
                } else if(chairsL.length!=0){ //EXISTE UN JUGADOR DESCONECTADO
                    playerRevoke = chairsL[0];
                    /*if(chairsL[0]==0 || chairsL[0]==2) pairLeave = 0;
                    if(chairsL[0]==1 || chairsL[0]==3) pairLeave = 1;*/
                } else {
                    console.log("***ERROR. La partida no se ha completado, nadie ha solicitado abandonar ni hay nadie desconectado...***");
                    return false;
                }

                if(finished){
                    auxSG.gameUpdated = true;
                    console.log("\t\t***Partida actualizada en BD (Mesa: "+_table+")*** Finished:"+finished+" Completed:"+completed+" Type:"+type+" playerLeave:"+playerLeave+" playerRevoke:"+playerRevoke+" pWon:"+pWon);
                    mongoJS.updateGameFinished(completed, type, pWon, playerRevoke, sets, points, p0, p1, p2, p3);
                } else console.log("**ERROR. Partida no actualizada: La partida no ha terminado...***");
            } else console.log("***OK. La partida ya ha sido actualizada. Table: "+_table+"***");
        } else console.log("***ERROR. Partida no actualizada: La partida no ha empezado...***");
    } else console.log("***FLAG. Partida no actualizada: Se ha desactivado la actualización de partidas. ***");
}

