function setUserLeaveGame(table, chair){
    var _game = games[table];
    if(_game!=null) _game[table].chairsLeave.push(chair);
}

//Reinicia las propiedades del usuario
function resetUser(id){
    var player = getUserOnline(id);
    if(player!=null){
        //console.log("***Reset User: "+player.name+"***");
        
        if(!player.ia){
            player.table = -1;
            player.chair = -1;
            player.host = false;
        }
        
        player.firstPair = -1;
        player.host = false;
        player.cards = [-1, -1, -1, -1];
        player.discardCards = [false, false, false, false];
        player.arrayButtonEventPhase = [];
        player.inGame = false;
    }
}

//resetUser();  Vaciar mesa;  Eliminar partida
function resetGame(_table){
    //var 
    
    for(var i=0; i<NUM_PLAYERS; i++){
        var auxPlayer = games[_table].players[i];
        
        if(auxPlayer!=null){ 
            resetUser(auxPlayer.id);         //Atributos del objeto usuario
            if(!auxPlayer.ia) tables[_table][i] = -1;   //Borra los jugadores de las mesas
        } else {
            tables[_table][i] = -1; //Si no se encuentra el usuario, se vacía la mesa (Significa que no es una IA)
        }
    }
    
    games[_table] = null;
}

//Enviar evento de abandono;  resetGame();
function endGame(table, chairPlayerOut){
    if(games[table]!=null){
        for(var i=0; i<NUM_PLAYERS; i++){
            var auxUser = games[table].players[i];
            
            if(auxUser!=null){
                //Envía evento de abandono
                if(games[table].gameStarted) io.to(auxUser.id).emit(EO_PLAYER_GAME_DISCONNECTED, chairPlayerOut);
                else io.to(auxUser.id).emit(EO_CANCEL_SETTINGS_GAME);
            }
        }
        
        resetGame(table);
    }
}

function checkIDInGameAndUserNull(_id){
    for(var i=0; i<NUM_TABLES; i++){
        for(var j=0; j<NUM_PLAYERS; j++){
            if(tables[i][j]==_id){
                if(tables[i][0]!=-1 && tables[i][1]!=-1 && tables[i][2]!=-1 && tables[i][3]!=-1){
                    games[i].gameFinished = true;
                    games[i].gameUpdated = true;
                    endGame(i,j);
                } else tables[i][j] = -1;
            }
        }
    }
}

function deleteUserAndSocket(_id){
    var auxUser = getUserOnline(_id);
    
    if(!auxUser.ia){
        if(auxUser!=false) console.log("("+usersOnline.length+")<--- "+auxUser.name+" ("+auxUser.id+") se ha desconectado. PAUSE:"+auxUser.userPauseGame+"\tLEAVE:"+auxUser.userLeave);
        else console.log("("+usersOnline.length+")<--- null ("+auxUser.id+") se ha desconectado.");

        for(var i=0; i<usersOnline.length; i++){
            if(usersOnline[i].id == _id){
                usersOnline.splice(i,1);
            }
        }
        for(var i=0; i<socketsOnline.length; i++){
            if(socketsOnline[i] == _id){
                socketsOnline.splice(i,1);
            }
        }
    }
}
